package com.kotoba.window;
import android.content.*;import android.util.AtomicFile;import org.json.*;import java.io.*;import java.util.*;
final class Store {
 static Store instance; final Context context; final ArrayList<JSONObject> words=new ArrayList<>(); JSONObject data; String warning="";
 static synchronized Store get(Context c){if(instance==null)instance=new Store(c.getApplicationContext());return instance;}
 Store(Context c){context=c;try{JSONArray a=new JSONArray(read(c.getAssets().open("vocab.json")));for(int i=0;i<a.length();i++)words.add(a.getJSONObject(i));}catch(Exception e){throw new RuntimeException(e);}try{data=new JSONObject(read(new AtomicFile(file()).openRead()));validate(data);}catch(FileNotFoundException e){data=fresh();}catch(Exception e){File backup=new File(context.getFilesDir(),"progress-unreadable-"+System.currentTimeMillis()+".json");boolean kept=file().renameTo(backup);warning=kept?"原进度异常，已保留独立备份。":"原进度异常，请勿继续评分，先备份应用数据。";data=fresh();}}
 File file(){return new File(context.getFilesDir(),"progress.json");}
 static String read(InputStream in)throws IOException{try(InputStream s=in;ByteArrayOutputStream b=new ByteArrayOutputStream()){byte[] buf=new byte[16384];int n;while((n=s.read(buf))>0){if(b.size()+n>32000000)throw new IOException("文件过大");b.write(buf,0,n);}return b.toString("UTF-8");}}
 static void put(JSONObject o,String k,Object v){try{o.put(k,v);}catch(JSONException e){throw new RuntimeException(e);}}
 static JSONObject fresh(){JSONObject o=new JSONObject(),s=new JSONObject();put(o,"Version",1);put(s,"Level",5);put(s,"Levels",new JSONArray(Arrays.asList(5)));put(s,"DailyNew",20);put(s,"Theme","Dark");put(s,"AutoSpeak",true);put(s,"Shuffle",false);put(s,"ShuffleSeed",new Random().nextInt());put(s,"Transparent",false);put(s,"BackgroundOpacity",.8);put(s,"ShowReading",true);put(o,"Settings",s);put(o,"Progress",new JSONObject());put(o,"DailyReviews",new JSONObject());put(o,"DailyNew",new JSONObject());return o;}
 JSONObject settings(){return data.optJSONObject("Settings");}JSONObject progress(){return data.optJSONObject("Progress");}
 JSONObject progress(JSONObject w){return w==null?null:progress().optJSONObject(w.optString("Id"));}
 synchronized boolean save(){AtomicFile f=new AtomicFile(file());FileOutputStream out=null;try{out=f.startWrite();out.write(data.toString().getBytes("UTF-8"));f.finishWrite(out);warning="";return true;}catch(Exception e){f.failWrite(out);warning="保存失败："+e.getMessage();return false;}}
 static long time(Object value){if(value instanceof Number)return ((Number)value).longValue();String s=String.valueOf(value);try{if(s.startsWith("/Date("))return Long.parseLong(s.substring(6,s.indexOf(')')));return Long.parseLong(s);}catch(Exception e){return 0;}}
 static String date(long t){return "/Date("+t+")/";}String day(){return new java.text.SimpleDateFormat("yyyy-MM-dd",Locale.US).format(new Date());}
 boolean includes(int l){JSONArray ls=settings().optJSONArray("Levels");if(ls==null)return settings().optInt("Level",5)==l;for(int i=0;i<ls.length();i++)if(ls.optInt(i)==l)return true;return false;}
 int count(String name){return data.optJSONObject(name).optInt(day(),0);}
 long order(String id){int h=0x811c9dc5^settings().optInt("ShuffleSeed");for(char c:id.toCharArray()){h^=c;h*=16777619;}h^=h>>>16;h*=0x85ebca6b;h^=h>>>13;h*=0xc2b2ae35;h^=h>>>16;return Integer.toUnsignedLong(h);}
 ArrayList<JSONObject> queue(){ArrayList<JSONObject>d=new ArrayList<>(),n=new ArrayList<>();long now=System.currentTimeMillis();for(JSONObject w:words){if(!includes(w.optInt("Level")))continue;JSONObject r=progress(w);if(r==null||r.optInt("Reviews")==0)n.add(w);else if(time(r.opt("Due"))<=now)d.add(w);}d.sort((a,b)->Long.compare(time(progress(a).opt("Due")),time(progress(b).opt("Due"))));if(settings().optBoolean("Shuffle"))n.sort((a,b)->Long.compare(order(a.optString("Id")),order(b.optString("Id"))));int left=Math.max(0,settings().optInt("DailyNew",20)-count("DailyNew"));d.addAll(n.subList(0,Math.min(left,n.size())));return d;}
 int due(){int n=0;for(JSONObject w:words){JSONObject r=progress(w);if(includes(w.optInt("Level"))&&r!=null&&r.optInt("Reviews")>0&&time(r.opt("Due"))<=System.currentTimeMillis())n++;}return n;}
 static double interval(JSONObject r,int g){boolean fresh=r==null||r.optInt("Reviews")==0;double old=fresh?0:r.optDouble("Interval");return g==1?1d/1440:g==2?Math.min(36500,Math.max(.25,old*1.2)):g==3?(fresh?1:Math.min(36500,Math.max(1,old*2.5))):(fresh?4:Math.min(36500,Math.max(4,old*3)));}
 static String preview(JSONObject r,int g){double d=interval(r,g);return d<1d/24?Math.round(d*1440)+" 分钟":d<1?String.format(Locale.US,"%.1f 小时",d*24):String.format(Locale.US,"%.1f 天",d);}
 void grade(JSONObject w,int g){JSONObject r=progress(w);boolean fresh=r==null||r.optInt("Reviews")==0;if(r==null){r=new JSONObject();put(r,"Id",w.optString("Id"));put(progress(),w.optString("Id"),r);}long now=System.currentTimeMillis();double interval=interval(r,g);if(fresh)put(r,"FirstSeen",date(now));if(g==1&&!fresh)put(r,"Lapses",r.optInt("Lapses")+1);put(r,"Reviews",r.optInt("Reviews")+1);put(r,"Interval",interval);put(r,"Due",date(now+(long)(interval*86400000)));put(data.optJSONObject("DailyReviews"),day(),count("DailyReviews")+1);if(fresh)put(data.optJSONObject("DailyNew"),day(),count("DailyNew")+1);}
 static void validate(JSONObject o)throws Exception{if(o.getInt("Version")!=1)throw new Exception("不支持的格式");JSONObject s=o.getJSONObject("Settings");o.getJSONObject("DailyReviews");o.getJSONObject("DailyNew");JSONObject p=o.getJSONObject("Progress");int daily=s.getInt("DailyNew");if(daily<0||daily>1000)throw new Exception("新词额度无效");JSONArray levels=s.optJSONArray("Levels");if(levels!=null){if(levels.length()<1||levels.length()>5)throw new Exception("等级无效");for(int i=0;i<levels.length();i++)if(levels.getInt(i)<1||levels.getInt(i)>5)throw new Exception("等级无效");}else if(s.getInt("Level")<1||s.getInt("Level")>5)throw new Exception("等级无效");if(p.length()>100000)throw new Exception("记录过多");Iterator<String> it=p.keys();while(it.hasNext()){String id=it.next();JSONObject r=p.getJSONObject(id);if(r.optInt("Reviews")<0||!id.equals(r.getString("Id")))throw new Exception("记录无效");}}
}